1	import { useState } from 'react';
2	import { X, CreditCard, Lock, ShieldCheck, Loader2 } from 'lucide-react';
3	import { PaymentMethodService } from '../services/paymentMethodService';
4	import type { SaveCardInput } from '../services/paymentMethodService';
5	import { useToast } from '../contexts/ToastContext';
6	import { logError } from '../lib/logger';
7	
8	interface AddCardModalProps {
9	  isOpen: boolean;
10	  onClose: () => void;
11	  onSuccess: () => void;
12	}
13	
14	interface FormState {
15	  number: string;
16	  expiryMonth: string;
17	  expiryYear: string;
18	  ccv: string;
19	  holderName: string;
20	  holderInfoName: string;
21	  holderInfoEmail: string;
22	  holderInfoCpfCnpj: string;
23	  holderInfoPostalCode: string;
24	  holderInfoAddressNumber: string;
25	  holderInfoPhone: string;
26	}
27	
28	const EMPTY_FORM: FormState = {
29	  number: '',
30	  expiryMonth: '',
31	  expiryYear: '',
32	  ccv: '',
33	  holderName: '',
34	  holderInfoName: '',
35	  holderInfoEmail: '',
36	  holderInfoCpfCnpj: '',
37	  holderInfoPostalCode: '',
38	  holderInfoAddressNumber: '',
39	  holderInfoPhone: '',
40	};
41	
42	function formatCardNumber(value: string): string {
43	  return value
44	    .replace(/\D/g, '')
45	    .slice(0, 16)
46	    .replace(/(.{4})/g, '$1 ')
47	    .trim();
48	}
49	
50	function formatCpfCnpj(value: string): string {
51	  const digits = value.replace(/\D/g, '').slice(0, 14);
52	  if (digits.length <= 11) {
53	    return digits
54	      .replace(/(\d{3})(\d)/, '$1.$2')
55	      .replace(/(\d{3})(\d)/, '$1.$2')
56	      .replace(/(\d{3})(\d{1,2})$/, '$1-$2');
57	  }
58	  return digits
59	    .replace(/(\d{2})(\d)/, '$1.$2')
60	    .replace(/(\d{3})(\d)/, '$1.$2')
61	    .replace(/(\d{3})(\d)/, '$1/$2')
62	    .replace(/(\d{4})(\d{1,2})$/, '$1-$2');
63	}
64	
65	function formatPhone(value: string): string {
66	  const digits = value.replace(/\D/g, '').slice(0, 11);
67	  if (digits.length <= 10) {
68	    return digits.replace(/(\d{2})(\d{4})(\d{0,4})/, '($1) $2-$3').trim();
69	  }
70	  return digits.replace(/(\d{2})(\d{5})(\d{0,4})/, '($1) $2-$3').trim();
71	}
72	
73	function formatCep(value: string): string {
74	  return value.replace(/\D/g, '').slice(0, 8).replace(/(\d{5})(\d{0,3})/, '$1-$2').trim();
75	}
76	
77	export default function AddCardModal({ isOpen, onClose, onSuccess }: AddCardModalProps) {
78	  const { addToast } = useToast();
79	  const [form, setForm] = useState<FormState>(EMPTY_FORM);
80	  const [loading, setLoading] = useState(false);
81	  const [errors, setErrors] = useState<Partial<Record<keyof FormState, string>>>({});
82	
83	  if (!isOpen) return null;
84	
85	  const handleChange = (field: keyof FormState, raw: string) => {
86	    let value = raw;
87	    if (field === 'number') value = formatCardNumber(raw);
88	    if (field === 'holderInfoCpfCnpj') value = formatCpfCnpj(raw);
89	    if (field === 'holderInfoPhone') value = formatPhone(raw);
90	    if (field === 'holderInfoPostalCode') value = formatCep(raw);
91	    if (field === 'expiryMonth') value = raw.replace(/\D/g, '').slice(0, 2);
92	    if (field === 'expiryYear') value = raw.replace(/\D/g, '').slice(0, 4);
93	    if (field === 'ccv') value = raw.replace(/\D/g, '').slice(0, 4);
94	    setForm((prev) => ({ ...prev, [field]: value }));
95	    if (errors[field]) setErrors((prev) => ({ ...prev, [field]: undefined }));
96	  };
97	
98	  const validate = (): boolean => {
99	    const newErrors: Partial<Record<keyof FormState, string>> = {};
100	    const digits = form.number.replace(/\s/g, '');
101	    if (digits.length < 13 || digits.length > 16) newErrors.number = 'Numero invalido (13-16 digitos)';
102	    const month = parseInt(form.expiryMonth, 10);
103	    if (!form.expiryMonth || month < 1 || month > 12) newErrors.expiryMonth = 'Mes invalido (01-12)';
104	    if (!form.expiryYear || form.expiryYear.length < 4) newErrors.expiryYear = 'Ano invalido (AAAA)';
105	    if (!form.ccv || form.ccv.length < 3) newErrors.ccv = 'CVV invalido';
106	    if (!form.holderName.trim()) newErrors.holderName = 'Nome do titular obrigatorio';
107	    if (!form.holderInfoName.trim()) newErrors.holderInfoName = 'Nome completo obrigatorio';
108	    if (!form.holderInfoEmail.trim() || !form.holderInfoEmail.includes('@')) newErrors.holderInfoEmail = 'E-mail invalido';
109	    const cpfCnpjDigits = form.holderInfoCpfCnpj.replace(/\D/g, '');
110	    if (cpfCnpjDigits.length !== 11 && cpfCnpjDigits.length !== 14) newErrors.holderInfoCpfCnpj = 'CPF (11 digitos) ou CNPJ (14 digitos)';
111	    const cepDigits = form.holderInfoPostalCode.replace(/\D/g, '');
112	    if (cepDigits.length !== 8) newErrors.holderInfoPostalCode = 'CEP invalido (8 digitos)';
113	    if (!form.holderInfoAddressNumber.trim()) newErrors.holderInfoAddressNumber = 'Numero do endereco obrigatorio';
114	    const phoneDigits = form.holderInfoPhone.replace(/\D/g, '');
115	    if (phoneDigits.length < 10) newErrors.holderInfoPhone = 'Telefone invalido';
116	    setErrors(newErrors);
117	    return Object.keys(newErrors).length === 0;
118	  };
119	
120	  const handleSubmit = async () => {
121	    if (!validate()) return;
122	    setLoading(true);
123	
124	    const input: SaveCardInput = {
125	      holderName: form.holderName.trim(),
126	      number: form.number.replace(/\s/g, ''),
127	      expiryMonth: form.expiryMonth,
128	      expiryYear: form.expiryYear,
129	      ccv: form.ccv,
130	      holderInfo: {
131	        name: form.holderInfoName.trim(),
132	        email: form.holderInfoEmail.trim(),
133	        cpfCnpj: form.holderInfoCpfCnpj.replace(/\D/g, ''),
134	        postalCode: form.holderInfoPostalCode.replace(/\D/g, ''),
135	        addressNumber: form.holderInfoAddressNumber.trim(),
136	        phone: form.holderInfoPhone.replace(/\D/g, ''),
137	      },
138	    };
139	
140	    try {
141	      const result = await PaymentMethodService.savePaymentMethod(input);
142	      if (!result.success) {
143	        addToast(result.error || 'Erro ao salvar cartao. Verifique os dados.', 'error');
144	        return;
145	      }
146	      addToast('Cartao adicionado com sucesso!', 'success');
147	      setForm(EMPTY_FORM);
148	      setErrors({});
149	      onSuccess();
150	      onClose();
151	    } catch (err: unknown) {
152	      logError('AddCardModal.handleSubmit', err);
153	      addToast('Erro inesperado ao salvar cartao.', 'error');
154	    } finally {
155	      setLoading(false);
156	    }
157	  };
158	
159	  const handleOverlayClick = () => {
160	    if (!loading) onClose();
161	  };
162	
163	  return (
164	    <div
165	      className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200"
166	      onClick={handleOverlayClick}
167	    >
168	      <div
169	        className="bg-white rounded-2xl border-2 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto"
170	        onClick={(e) => e.stopPropagation()}
171	      >
172	        {/* Header */}
173	        <div className="flex items-center justify-between mb-6">
174	          <div className="flex items-center gap-3">
175	            <div className="w-10 h-10 bg-black rounded-xl flex items-center justify-center">
176	              <CreditCard size={20} className="text-white" />
177	            </div>
178	            <h2 className="text-xl font-black uppercase tracking-tight">Adicionar Cartao</h2>
179	          </div>
180	          <button
181	            onClick={onClose}
182	            disabled={loading}
183	            aria-label="Fechar modal"
184	            className="p-2 hover:bg-gray-100 rounded-xl transition-colors disabled:opacity-50"
185	          >
186	            <X size={20} />
187	          </button>
188	        </div>
189	
190	        {/* Security notice */}
191	        <div className="bg-blue-50 border-2 border-blue-200 rounded-xl p-4 mb-6 flex gap-3 items-start">
192	          <ShieldCheck size={18} className="text-blue-600 flex-shrink-0 mt-0.5" />
193	          <div>
194	            <p className="text-xs font-black uppercase text-blue-700 mb-0.5">Pagamento Postpago — Sem cobranca antecipada</p>
195	            <p className="text-xs text-blue-600 font-medium">
196	              Seu cartao sera cobrado <strong>apenas na conclusao do turno</strong>. Os dados do cartao sao enviados
197	              diretamente ao Asaas (certificacao PCI DSS) e <strong>nao ficam armazenados no Worki</strong>.
198	            </p>
199	          </div>
200	        </div>
201	
202	        {/* Card details */}
203	        <section className="mb-6">
204	          <h3 className="text-sm font-black uppercase tracking-wide mb-4 flex items-center gap-2">
205	            <CreditCard size={16} /> Dados do Cartao
206	          </h3>
207	
208	          <div className="space-y-4">
209	            {/* Card number */}
210	            <div>
211	              <label htmlFor="card-number" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
212	                Numero do Cartao
213	              </label>
214	              <input
215	                id="card-number"
216	                type="text"
217	                inputMode="numeric"
218	                autoComplete="cc-number"
219	                placeholder="0000 0000 0000 0000"
220	                value={form.number}
221	                onChange={(e) => handleChange('number', e.target.value)}
222	                className={`w-full border-2 rounded-xl px-4 py-3 font-mono focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.number ? 'border-red-500' : 'border-black'}`}
223	              />
224	              {errors.number && <p className="text-xs text-red-500 mt-1 font-medium">{errors.number}</p>}
225	            </div>
226	
227	            {/* Expiry + CVV */}
228	            <div className="grid grid-cols-3 gap-3">
229	              <div>
230	                <label htmlFor="expiry-month" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
231	                  Mes
232	                </label>
233	                <input
234	                  id="expiry-month"
235	                  type="text"
236	                  inputMode="numeric"
237	                  autoComplete="cc-exp-month"
238	                  placeholder="MM"
239	                  value={form.expiryMonth}
240	                  onChange={(e) => handleChange('expiryMonth', e.target.value)}
241	                  className={`w-full border-2 rounded-xl px-4 py-3 font-mono focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.expiryMonth ? 'border-red-500' : 'border-black'}`}
242	                />
243	                {errors.expiryMonth && <p className="text-xs text-red-500 mt-1 font-medium">{errors.expiryMonth}</p>}
244	              </div>
245	              <div>
246	                <label htmlFor="expiry-year" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
247	                  Ano
248	                </label>
249	                <input
250	                  id="expiry-year"
251	                  type="text"
252	                  inputMode="numeric"
253	                  autoComplete="cc-exp-year"
254	                  placeholder="AAAA"
255	                  value={form.expiryYear}
256	                  onChange={(e) => handleChange('expiryYear', e.target.value)}
257	                  className={`w-full border-2 rounded-xl px-4 py-3 font-mono focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.expiryYear ? 'border-red-500' : 'border-black'}`}
258	                />
259	                {errors.expiryYear && <p className="text-xs text-red-500 mt-1 font-medium">{errors.expiryYear}</p>}
260	              </div>
261	              <div>
262	                <label htmlFor="ccv" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
263	                  CVV
264	                </label>
265	                <input
266	                  id="ccv"
267	                  type="password"
268	                  inputMode="numeric"
269	                  autoComplete="cc-csc"
270	                  placeholder="•••"
271	                  value={form.ccv}
272	                  onChange={(e) => handleChange('ccv', e.target.value)}
273	                  className={`w-full border-2 rounded-xl px-4 py-3 font-mono focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.ccv ? 'border-red-500' : 'border-black'}`}
274	                />
275	                {errors.ccv && <p className="text-xs text-red-500 mt-1 font-medium">{errors.ccv}</p>}
276	              </div>
277	            </div>
278	
279	            {/* Holder name on card */}
280	            <div>
281	              <label htmlFor="holder-name" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
282	                Nome no Cartao
283	              </label>
284	              <input
285	                id="holder-name"
286	                type="text"
287	                autoComplete="cc-name"
288	                placeholder="Como impresso no cartao"
289	                value={form.holderName}
290	                onChange={(e) => handleChange('holderName', e.target.value)}
291	                className={`w-full border-2 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.holderName ? 'border-red-500' : 'border-black'}`}
292	              />
293	              {errors.holderName && <p className="text-xs text-red-500 mt-1 font-medium">{errors.holderName}</p>}
294	            </div>
295	          </div>
296	        </section>
297	
298	        {/* Divider */}
299	        <div className="border-t-2 border-gray-100 mb-6" />
300	
301	        {/* Holder info */}
302	        <section className="mb-6">
303	          <h3 className="text-sm font-black uppercase tracking-wide mb-4 flex items-center gap-2">
304	            <Lock size={16} /> Dados do Titular (Antifraude)
305	          </h3>
306	
307	          <div className="space-y-4">
308	            <div>
309	              <label htmlFor="holder-full-name" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
310	                Nome Completo
311	              </label>
312	              <input
313	                id="holder-full-name"
314	                type="text"
315	                autoComplete="name"
316	                placeholder="Nome completo do titular"
317	                value={form.holderInfoName}
318	                onChange={(e) => handleChange('holderInfoName', e.target.value)}
319	                className={`w-full border-2 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.holderInfoName ? 'border-red-500' : 'border-black'}`}
320	              />
321	              {errors.holderInfoName && <p className="text-xs text-red-500 mt-1 font-medium">{errors.holderInfoName}</p>}
322	            </div>
