324	            <div>
325	              <label htmlFor="holder-email" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
326	                E-mail
327	              </label>
328	              <input
329	                id="holder-email"
330	                type="email"
331	                autoComplete="email"
332	                placeholder="email@empresa.com"
333	                value={form.holderInfoEmail}
334	                onChange={(e) => handleChange('holderInfoEmail', e.target.value)}
335	                className={`w-full border-2 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.holderInfoEmail ? 'border-red-500' : 'border-black'}`}
336	              />
337	              {errors.holderInfoEmail && <p className="text-xs text-red-500 mt-1 font-medium">{errors.holderInfoEmail}</p>}
338	            </div>
339	
340	            <div>
341	              <label htmlFor="holder-cpf-cnpj" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
342	                CPF / CNPJ
