369	                />
370	                {errors.holderInfoPostalCode && <p className="text-xs text-red-500 mt-1 font-medium">{errors.holderInfoPostalCode}</p>}
371	              </div>
372	              <div>
373	                <label htmlFor="holder-address-number" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
374	                  Numero
375	                </label>
376	                <input
377	                  id="holder-address-number"
378	                  type="text"
379	                  placeholder="Ex: 123"
380	                  value={form.holderInfoAddressNumber}
381	                  onChange={(e) => handleChange('holderInfoAddressNumber', e.target.value)}
382	                  className={`w-full border-2 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.holderInfoAddressNumber ? 'border-red-500' : 'border-black'}`}
383	                />
384	                {errors.holderInfoAddressNumber && <p className="text-xs text-red-500 mt-1 font-medium">{errors.holderInfoAddressNumber}</p>}
385	              </div>
386	            </div>
387	
388	            <div>
389	              <label htmlFor="holder-phone" className="block text-xs font-black uppercase mb-1.5 text-gray-700">
390	                Telefone
391	              </label>
392	              <input
393	                id="holder-phone"
394	                type="text"
395	                inputMode="tel"
396	                autoComplete="tel"
397	                placeholder="(00) 00000-0000"
398	                value={form.holderInfoPhone}
399	                onChange={(e) => handleChange('holderInfoPhone', e.target.value)}
400	                className={`w-full border-2 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors ${errors.holderInfoPhone ? 'border-red-500' : 'border-black'}`}
401	              />
402	              {errors.holderInfoPhone && <p className="text-xs text-red-500 mt-1 font-medium">{errors.holderInfoPhone}</p>}
403	            </div>
404	          </div>
405	        </section>
406	
407	        {/* Actions */}
408	        <div className="flex gap-3">
409	          <button
410	            onClick={onClose}
411	            disabled={loading}
412	            className="flex-1 py-3 border-2 border-black rounded-xl font-black uppercase hover:bg-gray-50 transition-colors disabled:opacity-50"
413	          >
