1	import { useState, useEffect, useCallback } from 'react';
2	import { CreditCard, Plus, Star, AlertCircle, Loader2 } from 'lucide-react';
3	import { PaymentMethodService } from '../services/paymentMethodService';
4	import type { PaymentMethod } from '../types';
5	import { logError } from '../lib/logger';
6	import AddCardModal from './AddCardModal';
7	
8	const BRAND_LABELS: Record<string, string> = {
9	  VISA: 'Visa',
10	  MASTERCARD: 'Mastercard',
11	  AMEX: 'American Express',
12	  ELO: 'Elo',
13	  HIPERCARD: 'Hipercard',
14	  DINERS: 'Diners',
15	};
16	
17	function getBrandLabel(brand?: string | null): string {
18	  if (!brand) return 'Cartao';
19	  return BRAND_LABELS[brand.toUpperCase()] ?? brand;
20	}
21	
22	function getBrandColor(brand?: string | null): string {
23	  const b = brand?.toUpperCase();
24	  if (b === 'VISA') return 'bg-blue-600';
25	  if (b === 'MASTERCARD') return 'bg-orange-500';
26	  if (b === 'ELO') return 'bg-yellow-500';
27	  if (b === 'AMEX') return 'bg-blue-800';
28	  return 'bg-gray-700';
29	}
30	
31	export default function PaymentMethodsSection() {
32	  const [cards, setCards] = useState<PaymentMethod[]>([]);
33	  const [loading, setLoading] = useState(true);
34	  const [modalOpen, setModalOpen] = useState(false);
35	
36	  const fetchCards = useCallback(async () => {
37	    setLoading(true);
38	    try {
39	      const data = await PaymentMethodService.listPaymentMethods();
40	      setCards(data);
41	    } catch (err: unknown) {
42	      logError('PaymentMethodsSection.fetchCards', err);
43	    } finally {
44	      setLoading(false);
45	    }
46	  }, []);
47	
48	  useEffect(() => {
49	    fetchCards();
50	  }, [fetchCards]);
51	
52	  const handleSaveSuccess = () => {
53	    fetchCards();
54	  };
55	
56	  return (
57	    <section className="bg-white border-2 border-black rounded-2xl p-6">
58	      {/* Section header */}
59	      <div className="flex items-center justify-between mb-6">
60	        <div className="flex items-center gap-3">
61	          <div className="w-9 h-9 bg-black rounded-xl flex items-center justify-center">
62	            <CreditCard size={18} className="text-white" />
63	          </div>
64	          <div>
65	            <h3 className="text-lg font-black uppercase tracking-tight">Cartoes de Credito</h3>
66	            <p className="text-xs text-gray-500 font-medium">Para pagamento postpago de turnos</p>
67	          </div>
68	        </div>
